const items = $input.all();
if (items.length === 0) return [];

let resultado = items.map(item => {
    let datosLimpios = item.json;

    // 1. Cogemos la fecha original del campo 'timestamp'
    let fecha = new Date(datosLimpios.timestamp); 

    // 2. Restamos 1 día
    fecha.setDate(fecha.getDate() - 1);

    // 3. Extraemos el año
    datosLimpios.year = fecha.getFullYear().toString();

    // 4. Extraemos el mes sumándole 1 y forzamos los 2 dígitos (ej: '05')
    datosLimpios.month = String(fecha.getMonth() + 1).padStart(2, '0');

    // 5. Extraemos el día y forzamos los 2 dígitos (ej: '08')
    datosLimpios.day = String(fecha.getDate()).padStart(2, '0');

    // Opcional: eliminar el timestamp original si quieres el JSON limpio
    // delete datosLimpios.timestamp; 

    return {
        json: datosLimpios
    };
});

return resultado;

const items = $input.all();
if (items.length === 0) return [];

let todasLasHoras = [];

// Recorremos los archivos descargados (las 24 horas)
for (let i = 0; i < items.length; i++) {
    // 1. ABRIMOS EL ARCHIVO BINARIO
    // Leemos el contenido de la propiedad 'data'
    let buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
    let contenidoJson = JSON.parse(buffer.toString('utf8'));

    // 2. CORRECCIÓN DE FORMATO
    // Si el JSON viene dentro de una lista [ {datos} ], extraemos el objeto
    if (Array.isArray(contenidoJson)) {
        contenidoJson = contenidoJson[0];
    }

    // 3. LIMPIEZA DE COLUMNAS PARA EL CSV
    // Eliminamos el año, mes y día explícitamente para que no sean columnas
    // delete contenidoJson.year;
    // delete contenidoJson.month;
    // delete contenidoJson.day;

    // 4. AÑADIMOS LA HORA A LA LISTA
    // Envolvemos el objeto en la etiqueta "json" que exige n8n por cada ítem
    todasLasHoras.push({ json: contenidoJson });
}

// 5. Devolvemos los 24 ítems sueltos a n8n
return todasLasHoras;
